      en: ["Designed by the architect Michele De Lucchi.", "The bridge is 150 meters long and opened in 2010."],
      es: ["Fue diseñado por el arquitecto Michele De Lucchi.", "El puente tiene 150 metros de largo y se inauguró en 2010."],
